import{_ as a,o as i,c as t,a4 as l}from"./chunks/framework.BNWYI55R.js";const c=JSON.parse('{"title":"林越 (Lin Yue)｜首席跨境网络评测工程师与架构师","description":"林越（Lin Yue）拥有 10 年以上跨国网络运维与专线架构实操背景，是 aijichang.blog 的首席技术作者与实验室负责人。","frontmatter":{"title":"林越 (Lin Yue)｜首席跨境网络评测工程师与架构师","description":"林越（Lin Yue）拥有 10 年以上跨国网络运维与专线架构实操背景，是 aijichang.blog 的首席技术作者与实验室负责人。","h1":"林越 (Lin Yue) - 首席网络架构师与评测作者档案","pageType":"author","canonicalPath":"/authors/lin-yue/","primaryIntent":"E-E-A-T 专家履历：展示核心作者的网络工程专业经历、评测方法论与最新发布文章","verifiedAt":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"authors/lin-yue/index.md","filePath":"authors/lin-yue/index.md","lastUpdated":1792569996000}'),r={name:"authors/lin-yue/index.md"};function n(o,e,s,u,h,d){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="林越-lin-yue-首席网络架构师与评测作者档案" tabindex="-1">林越 (Lin Yue) - 首席网络架构师与评测作者档案 <a class="header-anchor" href="#林越-lin-yue-首席网络架构师与评测作者档案" aria-label="Permalink to &quot;林越 (Lin Yue) - 首席网络架构师与评测作者档案&quot;">​</a></h1><blockquote><p>“网络协议没有玄学，每一帧卡顿与阻断的背后，都是路由拓扑、出口识别与风险策略的具体博弈。”</p></blockquote><hr><h2 id="个人专业经历与技术背景" tabindex="-1">个人专业经历与技术背景 <a class="header-anchor" href="#个人专业经历与技术背景" aria-label="Permalink to &quot;个人专业经历与技术背景&quot;">​</a></h2><p><strong>林越</strong> 是 aijichang.blog 的创始人之一兼首席技术评测工程师。毕业于计算机科学与技术专业，专注于计算机网络体系结构与分布式系统路由研究。</p><p>在加入跨境网络选购指南项目之前，林越曾先后在跨国软件企业与全球云计算服务集成商担任高级网络工程师与 SRE 架构师，累计深度管理过亚太区超过 40G 的跨国专线带宽（IEPL/IPLC），深度熟悉 BGP 动态多线调度、Anycast 节点分发以及 TLS 1.3、VLESS、Shadowsocks-2022、Sing-box 的内部实现机制。</p><h3 id="核心专长领域" tabindex="-1">核心专长领域 <a class="header-anchor" href="#核心专长领域" aria-label="Permalink to &quot;核心专长领域&quot;">​</a></h3><ul><li><strong>专线拓扑与延迟优化</strong>：精通电信 CN2 GIA、联通 9929、移动 CMIN2 等精品公网链路与内网专线的真实抗压边界；</li><li><strong>AI 任务长连接维护</strong>：针对 OpenAI、Claude、Gemini 的 SSE（Server-Sent Events）流式数据传输特性，设计并落地了一套防 TCP RST 与长连接心跳维活测评标准；</li><li><strong>流媒体 CDN 调度与原生出口核验</strong>：针对 Netflix 4K、Disney+ 与 YouTube Premium，制定了严格基于 MaxMind、IPinfo 数据库与平台本地住宅 IP 风险分（Fraud Score）的四层判别法。</li></ul><hr><h2 id="负责的核心专题与代表作" tabindex="-1">负责的核心专题与代表作 <a class="header-anchor" href="#负责的核心专题与代表作" aria-label="Permalink to &quot;负责的核心专题与代表作&quot;">​</a></h2><p>作为 aijichang.blog 的技术主笔，林越参与并主导了全站 8 大核心业务栏目的框架制定与 41 家机场实验室测试：</p><ol><li><strong><a href="/ai/">AI机场：ChatGPT、Claude与Gemini任务可用性比较</a></strong><ul><li>深入剖析大语言模型长文本多轮交互对跨国链路抖动与出口纯净度的苛刻要求；</li></ul></li><li><strong><a href="/methodology/">四层评测方法论与实验室标准</a></strong><ul><li>制定了包含“物理拓扑审计、真实任务闭环、晚高峰抗压丢包、商业合规与退款保障”在内的四层评测体系；</li></ul></li><li><strong><a href="/reviews/lightspeed/">光速云 8,000 字旗舰单品深度评测档案</a></strong><ul><li>从 147 永久套餐、轻量版、极速版到企业定制版，提供全尺寸抓包实测图集与客观选购指引；</li></ul></li><li><strong><a href="/guides/">AI使用指南：连接验证、节点配置与网络排障</a></strong><ul><li>为中文开发者提供从 Clash Verge、Sing-box 到命令行 API 调用的全流程实战避坑策略。</li></ul></li></ol><hr><h2 id="严正声明与评测道德约束" tabindex="-1">严正声明与评测道德约束 <a class="header-anchor" href="#严正声明与评测道德约束" aria-label="Permalink to &quot;严正声明与评测道德约束&quot;">​</a></h2><ol><li><strong>零特权测试</strong>：林越在执行所有测试时，坚决拒绝服务商开通的特权测试通道或白名单 IP 段，所有结论均基于线上在售真实套餐；</li><li><strong>客观事实至上</strong>：即使面对合作推广品牌，对于晚高峰丢包、流媒体证书报错或虚标速率等问题，依然在评测中如实归档并保留存证，绝不做选择性隐瞒；</li><li><strong>欢迎同行审阅</strong>：所有测试方法均公开透明，欢迎网络工程师与安全研究员复核验证并提交<a href="/corrections/">勘误建议</a>。</li></ol>',15)])])}const p=a(r,[["render",n]]);export{c as __pageData,p as default};
